<?php
namespace Delnavazan\Platform\Core\Application;
use Delnavazan\Platform\Core\Infrastructure\Repository\TeachingEligibilityRepository;

final class TeachingEligibilityService {
    public function __construct(private ?TeachingEligibilityRepository $repo=null){$this->repo??=new TeachingEligibilityRepository();}
    public function setEligibility(array $input):int{$this->admin();$teacher=Normalizer::id($input['teacher_id']??null);$course=Normalizer::id($input['course_id']??null);$status=Normalizer::one($input['status']??'active',['active','inactive'],'eligibility status');[$from,$until]=$this->dates($input);$reason=$this->reason($input['reason_code']??null);$now=current_time('mysql',true);$this->repo->begin();try{$teacherRow=$this->repo->teacherForUpdate($teacher);$courseRow=$this->repo->courseForUpdate($course);if(!$courseRow||!$teacherRow)throw new \InvalidArgumentException('Teacher and Course are required');$id=$this->repo->saveEligibility($teacher,$course,$status,$from,$until,$reason,$now,get_current_user_id()?:null);$this->repo->commit();return$id;}catch(\Throwable$e){$this->repo->rollback();throw$e;}}
    public function effectivelyEligible(int $teacherId,int $courseId):bool{return $this->repo->effectiveEligibility(Normalizer::id($teacherId),Normalizer::id($courseId),current_time('mysql',true));}
    /** Write only active academy courses selected from the existing catalogue by this Teacher. */
    public function setOwnCourses(array $courseIds): void {
        $user=(int)get_current_user_id();if($user<1)throw new \RuntimeException('Unauthorized');
        $availabilityRepo=new \Delnavazan\Platform\Core\Infrastructure\Repository\TeacherAvailabilityRepository();$teacher=$availabilityRepo->activeTeacherIdForUser($user)??$availabilityRepo->onboardingTeacherIdForUser($user);
        if(!$teacher)throw new \RuntimeException('Active ready Teacher required');
        $ids=array_values(array_unique(array_map(static fn($id)=>Normalizer::id($id),$courseIds)));
        if(count($ids)>30)throw new \InvalidArgumentException('Too many selected courses');
        $now=current_time('mysql',true);$this->repo->begin();try{
            $t=$this->repo->teacherForUpdate($teacher);if(!$t||$t->status!=='active'||$t->archived_at!==null)throw new \InvalidArgumentException('Active Teacher required');
            $catalog=$this->ownCourseCatalogue();$allowed=array_fill_keys(array_map(static fn($row)=>(int)$row->course_id,$catalog),true);foreach($ids as $course){if(!isset($allowed[$course]))throw new \InvalidArgumentException('Choose only active academy courses');$this->repo->saveEligibility($teacher,$course,'active',null,null,'teacher_self_service',$now,$user);}foreach($this->repo->ownEligibilityRowsForUpdate($teacher) as $row)if($row->status==='active'&&!in_array((int)$row->course_id,$ids,true))$this->repo->saveEligibility($teacher,(int)$row->course_id,'inactive',null,null,'teacher_self_service_removed',$now,$user);
            $this->repo->commit();
        }catch(\Throwable $e){$this->repo->rollback();throw$e;}
    }
    public function ownCourseCatalogue(): array {
        $user=(int)get_current_user_id();if($user<1)throw new \RuntimeException('Unauthorized');$availabilityRepo=new \Delnavazan\Platform\Core\Infrastructure\Repository\TeacherAvailabilityRepository();$teacher=$availabilityRepo->activeTeacherIdForUser($user)??$availabilityRepo->onboardingTeacherIdForUser($user);if(!$teacher)throw new \RuntimeException('Linked Teacher required');
        global $wpdb;$p=$wpdb->prefix.'dzn_';$rows=$wpdb->get_results($wpdb->prepare("SELECT c.id course_id,c.instrument_id,c.default_duration_minutes,c.default_buffer_minutes,COALESCE(NULLIF(i.name_en,''),i.name_fa) instrument,COALESCE(NULLIF(c.name_en,''),c.name_fa) course,EXISTS(SELECT 1 FROM {$p}teacher_course_eligibilities e WHERE e.teacher_id=%d AND e.course_id=c.id AND e.status='active') selected FROM {$p}courses c INNER JOIN {$p}instruments i ON i.id=c.instrument_id WHERE c.status='active' AND c.archived_at IS NULL AND i.status='active' AND i.archived_at IS NULL ORDER BY instrument,course",$teacher));if($wpdb->last_error!=='')throw new \RuntimeException('Teaching eligibility authority unavailable');return is_array($rows)?$rows:array();
    }
    public function setOwnInstruments(array $instrumentIds): void { $ids=array_values(array_unique(array_map(static fn($id)=>Normalizer::id($id),$instrumentIds)));if(count($ids)>30)throw new \InvalidArgumentException('Too many selected instruments');$wanted=array_fill_keys($ids,true);$courses=[];foreach($this->ownCourseCatalogue() as $row)if(isset($wanted[(int)$row->instrument_id]))$courses[]=(int)$row->course_id;foreach($ids as $id){$exists=false;foreach($this->ownCourseCatalogue() as $row)if((int)$row->instrument_id===$id){$exists=true;break;}if(!$exists)throw new \InvalidArgumentException('Choose only existing academy instruments');}$this->setOwnCourses($courses); }
    public function setOwnAcceptingState(string $state): void { $user=(int)get_current_user_id();if($user<1)throw new \RuntimeException('Unauthorized');$ar=new \Delnavazan\Platform\Core\Infrastructure\Repository\TeacherAvailabilityRepository();$teacher=$ar->activeTeacherIdForUser($user);if(!$teacher)throw new \RuntimeException('Active ready Teacher required');$state=Normalizer::one($state,['accepting','limited','paused'],'accepting state');$now=current_time('mysql',true);$this->repo->begin();try{$t=$this->repo->teacherForUpdate($teacher);if(!$t||$t->status!=='active'||$t->archived_at!==null)throw new \InvalidArgumentException('Active Teacher required');$this->repo->saveAccepting($teacher,$state,'teacher_self_service',$now,$user);$this->repo->commit();}catch(\Throwable $e){$this->repo->rollback();throw$e;} }
    private function admin():void{if(!current_user_can('dzn_manage_teaching_eligibility'))throw new \RuntimeException('Unauthorized');}
    private function dates(array $input):array{$from=$this->utcDate($input['effective_from']??null);$until=$this->utcDate($input['effective_until']??null);if($from&&$until&&$until<=$from)throw new \InvalidArgumentException('Eligibility end must follow start');return[$from,$until];}
    private function utcDate(mixed $value):?string{if($value===null||$value==='')return null;$date=\DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',(string)$value,new \DateTimeZone('UTC'));if(!$date||$date->format('Y-m-d H:i:s')!==(string)$value)throw new \InvalidArgumentException('Invalid UTC effective date');return(string)$value;}
    private function reason(mixed $value):?string{return Normalizer::text($value,64);}
}
